WITH lines AS (SELECT id, effective_from, currency, EXPLODE(discounts) AS element FROM price_tiers) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, COUNT(*) FILTER (WHERE currency = 'USD') AS usd_rows, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list, PERCENTILE_APPROX(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, ROUND(AVG(element), 2) AS avg_element FROM lines GROUP BY DATE_TRUNC('QUARTER', effective_from) ORDER BY avg_element DESC
